// Georgian month endings: "26 ნოემბერი" → "26 ნოემბრამდე" / "26 ნოემბრიდან"
const KA_STEM = { 'იანვარი': 'იანვრ', 'თებერვალი': 'თებერვლ', 'მარტი': 'მარტ', 'აპრილი': 'აპრილ', 'მაისი': 'მაის', 'ივნისი': 'ივნის', 'ივლისი': 'ივლის', 'აგვისტო': 'აგვისტო', 'სექტემბერი': 'სექტემბრ', 'ოქტომბერი': 'ოქტომბრ', 'ნოემბერი': 'ნოემბრ', 'დეკემბერი': 'დეკემბრ' };
function kaCase(s, kind) {
  for (const [m, st] of Object.entries(KA_STEM)) if (s.endsWith(m)) {
    const vowel = st.endsWith('ო');
    return s.slice(0, -m.length) + st + (kind === 'მდე' ? (vowel ? 'მდე' : 'ამდე') : (vowel ? 'დან' : 'იდან'));
  }
  return s + '-' + kind;
}
